settings.customCss:
/* MegaForm Gen-3 scroll-aware single-page shell: cv-registration */
.mfp.mfp-cv-registration{--cvx-page:#f2f2f2;--cvx-paper:#ffffff;--cvx-ink:#2b2b2b;--cvx-muted:#777777;--cvx-line:#c8c8c8;--cvx-input:#fff;--cvx-primary:#2b2b2b;--cvx-soft:#e8e8e8;--cvx-error:#c0392b;--cvx-font:Georgia,"Times New Roman",serif;--cvx-display:Georgia,"Times New Roman",serif;--mf-form-radius:0px;--mf-btn-bg:var(--cvx-primary);--mf-font-family:var(--cvx-font);display:block!important;width:100%!important;max-width:none!important;margin:0 auto!important;padding:32px 16px 48px!important;border:0!important;border-radius:0!important;outline:0!important;background:#f2f2f2!important;color:var(--cvx-ink)!important;box-shadow:none!important;font-family:var(--cvx-font)!important;font-synthesis:none;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased;opacity:1!important}
.mfp.mfp-cv-registration,.mfp.mfp-cv-registration *,.mfp.mfp-cv-registration *::before,.mfp.mfp-cv-registration *::after{box-sizing:border-box}
.mf-form-wrapper .mf-form-inner .mfp.mfp-cv-registration{display:block!important;width:100%!important;max-width:none!important;margin-inline:auto!important}
.mfp-cv-registration .mfp-stage{width:100%;max-width:672px!important;margin-inline:auto!important;padding:0!important;border:0!important;border-radius:0!important;outline:0!important;background:transparent!important;box-shadow:none!important}
.mfp-cv-registration .mfp-paper{position:relative;width:100%;max-width:672px!important;margin:0 auto!important;border:0!important;outline:0!important;background:var(--cvx-paper)!important;box-shadow:0 20px 45px rgba(40,31,20,.14)}
.mfp-cv-registration .mfp-body{position:relative;padding:12px 32px 36px}
.mfp-cv-registration .mfp-section-head{display:flex;align-items:center;gap:11px;margin:26px 0 16px}.mfp-cv-registration .mfp-section-head h2{margin:0!important;padding:0!important;color:var(--cvx-ink)!important;font-family:var(--cvx-font)!important;font-size:12px!important;font-weight:900!important;line-height:1.2!important;letter-spacing:.14em!important;text-transform:uppercase!important}.mfp-cv-registration .mfp-section-head>span:last-child{height:1px;flex:1;background:var(--cvx-line)}
.mfp-cv-registration .mfp-section-icon{display:grid;width:30px;height:30px;flex:0 0 auto;place-items:center;border-radius:8px;background:var(--cvx-soft);color:var(--cvx-primary);font-size:14px;font-weight:900}
.mfp-cv-registration .mfp-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 20px}.mfp-cv-registration .mfp-stack{display:grid;gap:16px}.mfp-cv-registration .mfp-wide{margin-top:16px}.mfp-cv-registration .mf-field-group{min-width:0;margin:0}
.mfp-cv-registration .mf-field-label{display:block;margin:0 0 6px;color:var(--cvx-muted);font-size:10px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.mfp-cv-registration .mf-required{color:var(--cvx-error)}
.mfp-cv-registration .mf-input,.mfp-cv-registration .mf-select,.mfp-cv-registration .mf-textarea,.mfp-cv-registration input:not([type='checkbox']):not([type='radio']),.mfp-cv-registration select,.mfp-cv-registration textarea{width:100%!important;min-height:43px!important;padding:9px 12px!important;border:1px solid var(--cvx-line)!important;border-radius:8px!important;outline:0!important;background:var(--cvx-input)!important;color:var(--cvx-ink)!important;box-shadow:none!important;font:inherit!important;font-size:14px!important}
.mfp-cv-registration .mf-textarea,.mfp-cv-registration textarea{min-height:112px!important;resize:vertical!important}.mfp-cv-registration .mf-input:focus,.mfp-cv-registration .mf-select:focus,.mfp-cv-registration .mf-textarea:focus,.mfp-cv-registration input:focus,.mfp-cv-registration select:focus,.mfp-cv-registration textarea:focus{border-color:var(--cvx-primary)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--cvx-primary) 14%,transparent)!important}
.mfp-cv-registration input::placeholder,.mfp-cv-registration textarea::placeholder{color:color-mix(in srgb,var(--cvx-muted) 58%,transparent)}.mfp-cv-registration .mf-field-error{margin-top:5px;color:var(--cvx-error);font-size:11px}
.mfp-cv-registration .mfp-chip .mf-option-group{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important}.mfp-cv-registration .mfp-chip .mf-option-item{display:inline-flex!important;width:auto!important;margin:0!important;padding:0!important}.mfp-cv-registration .mfp-chip .mf-option-control{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;clip-path:inset(50%)!important}
.mfp-cv-registration .mfp-chip .mf-option-ui{display:inline-flex!important;min-height:32px!important;align-items:center!important;padding:7px 12px!important;border:1px solid var(--cvx-line)!important;border-radius:999px!important;background:var(--cvx-input)!important;color:var(--cvx-muted)!important;box-shadow:none!important}.mfp-cv-registration .mfp-chip .mf-option-label{color:inherit!important;font-size:12px!important;font-weight:700!important}.mfp-cv-registration .mfp-chip .mf-option-control:checked + .mf-option-ui{border-color:var(--cvx-primary)!important;background:var(--cvx-soft)!important;color:var(--cvx-primary)!important}
.mfp-cv-registration .mfp-check .mf-option-group{display:block!important}.mfp-cv-registration .mfp-check .mf-option-item{display:flex!important;align-items:flex-start!important;gap:9px!important;margin:0!important;padding:0!important}.mfp-cv-registration .mfp-check .mf-option-control{position:static!important;width:17px!important;height:17px!important;flex:0 0 17px!important;margin:3px 0 0!important;accent-color:var(--cvx-primary)!important;opacity:1!important}.mfp-cv-registration .mfp-check .mf-option-ui{display:block!important;min-width:0!important;padding:0!important;border:0!important;background:transparent!important;color:var(--cvx-muted)!important}.mfp-cv-registration .mfp-check .mf-option-label{display:block!important;color:inherit!important;font-size:13px!important;line-height:1.5!important}.mfp-cv-registration .mfp-consent-check .mf-field-label{display:none!important}.mfp-cv-registration .mfp-consent-check .mf-option-item{align-items:center!important}.mfp-cv-registration .mfp-consent-check .mf-option-control{margin:0!important}.mfp-cv-registration .mfp-consent-check .mf-option-ui{display:flex!important;align-items:center!important;min-height:20px!important}
.mfp-cv-registration .mfp-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:26px;padding-top:22px;border-top:1px solid var(--cvx-line);color:var(--cvx-muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.mfp-cv-registration .mfp-btn{display:inline-flex!important;min-height:44px;align-items:center;justify-content:center;gap:8px;border:0!important;border-radius:999px;padding:11px 22px;background:var(--cvx-primary)!important;color:#fff!important;font-family:var(--cvx-font)!important;font-size:12px!important;font-weight:900!important;line-height:1.4!important;letter-spacing:.08em!important;text-transform:uppercase!important;cursor:pointer}
.mfp-cv-registration .mfp-hidden{display:none!important}.mfp-cv-registration .mf-form-title,.mfp-cv-registration .mf-form-description,.mfp-cv-registration .mf-success-message,.mfp-cv-registration .mf-form-actions{display:none!important}.mf-form-wrapper.mf-custom-shell-mode.mf-custom-html-mode,.mf-form-wrapper.mf-custom-shell-mode.mf-custom-html-mode>.mf-form-inner,.mf-form-wrapper.mf-custom-shell-mode.mf-custom-html-mode>.mf-form-inner>.mf-form,.mf-form-wrapper.mf-custom-shell-mode.mf-custom-html-mode .mf-fields-container,.mf-form-wrapper:has(.mfp-cv-registration),.mf-form-wrapper:has(.mfp-cv-registration) .mf-form,.mf-form-wrapper:has(.mfp-cv-registration) .mf-form-inner,.mf-form-wrapper:has(.mfp-cv-registration) .mf-fields-container{--mf-page-bg:transparent!important;--mf-form-bg:transparent!important;--mf-card-bg:transparent!important;width:100%!important;max-width:none!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;outline:0!important;background:transparent!important;background-image:none!important;box-shadow:none!important;filter:none!important}.mf-form-wrapper:has(.mfp-cv-registration)::before,.mf-form-wrapper:has(.mfp-cv-registration)::after,.mf-form-wrapper:has(.mfp-cv-registration) .mf-form::before,.mf-form-wrapper:has(.mfp-cv-registration) .mf-form::after,.mf-form-wrapper:has(.mfp-cv-registration) .mf-form-inner::before,.mf-form-wrapper:has(.mfp-cv-registration) .mf-form-inner::after,.mf-form-wrapper:has(.mfp-cv-registration) .mf-fields-container::before,.mf-form-wrapper:has(.mfp-cv-registration) .mf-fields-container::after{display:none!important;content:none!important}.mf-form-wrapper:has(.mfp-cv-registration) .mf-form-actions{display:none!important}
@media(max-width:700px){.mfp-cv-registration .mfp-body{padding:8px 20px 28px}.mfp-cv-registration .mfp-row{grid-template-columns:1fr;gap:15px}}
@media(max-width:440px){.mfp.mfp-cv-registration{padding:12px 8px 28px!important}.mfp-cv-registration .mfp-body{padding:6px 16px 24px}.mfp-cv-registration .mfp-actions{align-items:stretch;flex-direction:column-reverse}.mfp-cv-registration .mfp-btn{width:100%}}

.mfp-cv-registration .mfp-paper{border:0!important;border-radius:0!important;box-shadow:0 14px 36px rgba(0,0,0,.16)}.mfp-cv-registration .mfp-header{display:grid;grid-template-columns:1fr 80px;gap:20px;padding:32px 32px 20px;border-bottom:4px solid #2b2b2b}.mfp-cv-registration .mfp-name{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 20px}.mfp-cv-registration .mfp-job{grid-column:1/-1}.mfp-cv-registration .mfp-photo{display:grid;width:80px;height:96px;place-items:center;border:1px solid #c8c8c8;background:#e8e8e8;color:#9a9a9a;font-size:9px;text-transform:uppercase}
.mfp-cv-registration .mfp-cv-grid{display:grid;grid-template-columns:200px minmax(0,1fr)}.mfp-cv-registration .mfp-sidebar{padding:6px 24px 28px;border-right:1px solid #c8c8c8;background:#f8f8f8}.mfp-cv-registration .mfp-main{padding:6px 28px 30px}.mfp-cv-registration .mfp-section-head{margin:28px 0 12px;padding-bottom:6px;border-bottom:1px solid #c8c8c8}.mfp-cv-registration .mfp-section-icon{width:24px;height:24px;border-radius:0;background:#e8e8e8;color:#2b2b2b}.mfp-cv-registration .mfp-section-head h2{font-size:11px!important;letter-spacing:.2em!important}.mfp-cv-registration .mfp-section-head>span:last-child{display:none}.mfp-cv-registration .mfp-note{margin:-4px 0 9px!important;color:#9a9a9a!important;font-size:11px!important;line-height:1.4!important}.mfp-cv-registration .mfp-span{grid-column:1/-1}
.mfp-cv-registration .mf-input,.mfp-cv-registration .mf-select,.mfp-cv-registration .mf-textarea,.mfp-cv-registration input:not([type='checkbox']):not([type='radio']),.mfp-cv-registration select,.mfp-cv-registration textarea{padding:7px 3px!important;border:0!important;border-bottom:1px solid #cacaca!important;border-radius:0!important;background:transparent!important;font-family:Georgia,"Times New Roman",serif!important}.mfp-cv-registration .mf-input:focus,.mfp-cv-registration .mf-select:focus,.mfp-cv-registration .mf-textarea:focus{box-shadow:none!important}.mfp-cv-registration .mfp-header .mf-input{font-size:17px!important;font-weight:700!important}.mfp-cv-registration .mfp-job .mf-input{color:#c0392b!important;font-size:13px!important;font-style:italic!important;font-weight:400!important}.mfp-cv-registration .mfp-sidebar .mfp-stack{gap:9px}.mfp-cv-registration .mfp-sidebar .mf-input{font-size:12px!important}
.mfp-cv-registration .mfp-list .mf-option-group{display:grid!important;grid-template-columns:1fr!important;gap:6px!important}.mfp-cv-registration .mfp-list .mf-option-item{display:flex!important;gap:7px!important;margin:0!important;padding:0!important}.mfp-cv-registration .mfp-list .mf-option-control{position:static!important;width:14px!important;height:14px!important;margin:0!important;opacity:1!important}.mfp-cv-registration .mfp-list .mf-option-ui{min-width:0!important;padding:0!important;border:0!important;background:transparent!important}.mfp-cv-registration .mfp-list .mf-option-label{overflow-wrap:anywhere;color:#5a5a5a!important;font-size:11px!important}.mfp.mfp-cv-registration{--mf-btn-radius:0}.mfp-cv-registration .mfp-btn{border-radius:0}
@media(max-width:680px){.mfp-cv-registration .mfp-header{grid-template-columns:1fr 64px;padding:22px 20px 18px}.mfp-cv-registration .mfp-photo{width:64px;height:80px}.mfp-cv-registration .mfp-cv-grid{grid-template-columns:1fr}.mfp-cv-registration .mfp-sidebar{border-right:0;border-bottom:1px solid #c8c8c8}.mfp-cv-registration .mfp-main{padding:6px 20px 26px}}@media(max-width:440px){.mfp-cv-registration .mfp-name{grid-template-columns:1fr}.mfp-cv-registration .mfp-job{grid-column:auto}.mfp-cv-registration .mfp-photo{display:none}.mfp-cv-registration .mfp-header{grid-template-columns:1fr}}
